CREATE TABLE project(singleton INTEGER PRIMARY KEY CHECK(singleton=1), id TEXT NOT NULL UNIQUE, title TEXT NOT NULL, author TEXT NOT NULL DEFAULT '', genre TEXT NOT NULL DEFAULT '', synopsis TEXT NOT NULL DEFAULT '', target_words INTEGER CHECK(target_words IS NULL OR target_words>=0), story_epoch_label TEXT NOT NULL DEFAULT 'Day 0', story_calendar_id TEXT, settings TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TRIGGER project_identity_immutable BEFORE UPDATE OF id,singleton ON project BEGIN SELECT RAISE(ABORT,'project identity is immutable'); END;
CREATE TRIGGER project_no_delete BEFORE DELETE ON project BEGIN SELECT RAISE(ABORT,'project identity cannot be deleted'); END;
CREATE TABLE structural_node(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES structural_node(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK(kind IN('section','chapter','group')), title TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), target_words INTEGER CHECK(target_words IS NULL OR target_words>=0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(parent_id,position));
CREATE UNIQUE INDEX structural_root_position ON structural_node(position) WHERE parent_id IS NULL;
CREATE INDEX structural_siblings ON structural_node(parent_id,position);
CREATE TRIGGER structural_no_cycle BEFORE UPDATE OF parent_id ON structural_node WHEN NEW.parent_id IS NOT NULL BEGIN SELECT CASE WHEN NEW.parent_id=NEW.id OR EXISTS(WITH RECURSIVE ancestors(id) AS (SELECT NEW.parent_id UNION ALL SELECT n.parent_id FROM structural_node n JOIN ancestors a ON n.id=a.id WHERE n.parent_id IS NOT NULL) SELECT 1 FROM ancestors WHERE id=NEW.id) THEN RAISE(ABORT,'structural cycle') END; END;
CREATE TRIGGER structural_parent_kind_insert BEFORE INSERT ON structural_node WHEN NEW.parent_id IS NOT NULL BEGIN SELECT CASE WHEN (SELECT kind FROM structural_node WHERE id=NEW.parent_id)='chapter' THEN RAISE(ABORT,'chapter cannot contain structural nodes') END; END;
CREATE TRIGGER structural_parent_kind_update BEFORE UPDATE OF parent_id ON structural_node WHEN NEW.parent_id IS NOT NULL BEGIN SELECT CASE WHEN (SELECT kind FROM structural_node WHERE id=NEW.parent_id)='chapter' THEN RAISE(ABORT,'chapter cannot contain structural nodes') END; END;
CREATE TABLE character(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE location(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE plotline(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE story_event(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', time_nominal INTEGER, time_lower INTEGER, time_upper INTEGER, time_precision TEXT NOT NULL DEFAULT 'unknown', end_nominal INTEGER, end_lower INTEGER, end_upper INTEGER, end_precision TEXT NOT NULL DEFAULT 'unknown', source_time_text TEXT NOT NULL DEFAULT '');
CREATE TABLE scene(id TEXT PRIMARY KEY, title TEXT NOT NULL DEFAULT '', synopsis TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'idea', target_words INTEGER CHECK(target_words IS NULL OR target_words>=0), purpose TEXT NOT NULL DEFAULT '', goal TEXT NOT NULL DEFAULT '', outcome TEXT NOT NULL DEFAULT '', start_nominal INTEGER, start_lower INTEGER, start_upper INTEGER, start_precision TEXT NOT NULL DEFAULT 'unknown', end_nominal INTEGER, end_lower INTEGER, end_upper INTEGER, end_precision TEXT NOT NULL DEFAULT 'unknown', pov_character_id TEXT REFERENCES character(id) ON DELETE RESTRICT, start_location_id TEXT REFERENCES location(id) ON DELETE RESTRICT, end_location_id TEXT REFERENCES location(id) ON DELETE RESTRICT, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE scene_placement(scene_id TEXT PRIMARY KEY REFERENCES scene(id) ON DELETE CASCADE, chapter_id TEXT NOT NULL REFERENCES structural_node(id) ON DELETE RESTRICT, position INTEGER NOT NULL CHECK(position>=0), UNIQUE(chapter_id,position));
CREATE TRIGGER placement_chapter_insert BEFORE INSERT ON scene_placement BEGIN SELECT CASE WHEN (SELECT kind FROM structural_node WHERE id=NEW.chapter_id)!='chapter' THEN RAISE(ABORT,'destination must be chapter') END; END;
CREATE TRIGGER placement_chapter_update BEFORE UPDATE OF chapter_id ON scene_placement BEGIN SELECT CASE WHEN (SELECT kind FROM structural_node WHERE id=NEW.chapter_id)!='chapter' THEN RAISE(ABORT,'destination must be chapter') END; END;
CREATE TRIGGER node_kind_protect BEFORE UPDATE OF kind ON structural_node WHEN OLD.kind='chapter' AND NEW.kind!='chapter' AND EXISTS(SELECT 1 FROM scene_placement WHERE chapter_id=OLD.id) BEGIN SELECT RAISE(ABORT,'chapter contains scenes'); END;
CREATE TRIGGER node_delete_protect BEFORE DELETE ON structural_node WHEN EXISTS(SELECT 1 FROM scene_placement WHERE chapter_id=OLD.id) OR EXISTS(SELECT 1 FROM structural_node WHERE parent_id=OLD.id) BEGIN SELECT RAISE(ABORT,'node has dependents'); END;
CREATE TABLE scene_content(scene_id TEXT PRIMARY KEY REFERENCES scene(id) ON DELETE CASCADE, relative_path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK(byte_length>=0), generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE scene_character(scene_id TEXT NOT NULL REFERENCES scene(id) ON DELETE CASCADE, character_id TEXT NOT NULL REFERENCES character(id) ON DELETE RESTRICT, participation_role TEXT NOT NULL CHECK(participation_role IN('pov','major','minor','off_camera','mentioned')), notes TEXT NOT NULL DEFAULT '', PRIMARY KEY(scene_id,character_id,participation_role));
CREATE TABLE scene_plotline(scene_id TEXT NOT NULL REFERENCES scene(id) ON DELETE CASCADE, plotline_id TEXT NOT NULL REFERENCES plotline(id) ON DELETE RESTRICT, role TEXT NOT NULL DEFAULT 'advances', share_basis_points INTEGER CHECK(share_basis_points IS NULL OR (share_basis_points BETWEEN 0 AND 10000)), PRIMARY KEY(scene_id,plotline_id));
CREATE TABLE scene_event(scene_id TEXT NOT NULL REFERENCES scene(id) ON DELETE CASCADE, event_id TEXT NOT NULL REFERENCES story_event(id) ON DELETE RESTRICT, relationship_kind TEXT NOT NULL DEFAULT 'depicts', PRIMARY KEY(scene_id,event_id,relationship_kind));
CREATE TABLE custom_field_definition(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, field_type TEXT NOT NULL CHECK(field_type IN('text','long_text','integer','decimal','boolean','datetime','enum','entity_ref','entity_refs')), required INTEGER NOT NULL DEFAULT 0 CHECK(required IN(0,1)), default_text TEXT, default_integer INTEGER, default_decimal TEXT, default_boolean INTEGER CHECK(default_boolean IS NULL OR default_boolean IN(0,1)), enum_values TEXT NOT NULL DEFAULT '', reference_kind TEXT);
CREATE TABLE custom_field_value(scene_id TEXT NOT NULL REFERENCES scene(id) ON DELETE CASCADE, field_id TEXT NOT NULL REFERENCES custom_field_definition(id) ON DELETE RESTRICT, text_value TEXT, integer_value INTEGER, decimal_value TEXT, boolean_value INTEGER CHECK(boolean_value IS NULL OR boolean_value IN(0,1)), entity_ref TEXT, PRIMARY KEY(scene_id,field_id));
CREATE TABLE custom_field_entity_ref(scene_id TEXT NOT NULL, field_id TEXT NOT NULL, ordinal INTEGER NOT NULL, target_kind TEXT NOT NULL, target_id TEXT NOT NULL, character_id TEXT REFERENCES character(id) ON DELETE RESTRICT, location_id TEXT REFERENCES location(id) ON DELETE RESTRICT, plotline_id TEXT REFERENCES plotline(id) ON DELETE RESTRICT, event_id TEXT REFERENCES story_event(id) ON DELETE RESTRICT, scene_id_ref TEXT REFERENCES scene(id) ON DELETE RESTRICT, PRIMARY KEY(scene_id,field_id,ordinal), FOREIGN KEY(scene_id,field_id) REFERENCES custom_field_value(scene_id,field_id) ON DELETE CASCADE, CHECK((character_id IS NOT NULL)+(location_id IS NOT NULL)+(plotline_id IS NOT NULL)+(event_id IS NOT NULL)+(scene_id_ref IS NOT NULL)=1));
CREATE TABLE write_journal(tx_id TEXT PRIMARY KEY, scene_id TEXT NOT NULL REFERENCES scene(id) ON DELETE CASCADE, target_path TEXT NOT NULL, temp_path TEXT NOT NULL, candidate_path TEXT NOT NULL, old_hash TEXT, new_hash TEXT NOT NULL, new_length INTEGER NOT NULL, next_generation INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN('prepared','db_committed')), created_at TEXT NOT NULL);
CREATE TABLE write_conflict(tx_id TEXT PRIMARY KEY, scene_id TEXT NOT NULL, recovery_path TEXT NOT NULL, expected_hash TEXT, actual_hash TEXT, candidate_hash TEXT, created_at TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0, decision INTEGER NOT NULL DEFAULT 0 CHECK(decision IN(0,1,2)));
CREATE TABLE import_run(id TEXT PRIMARY KEY, source_type TEXT NOT NULL, source_identifier TEXT NOT NULL, source_fingerprint TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, status TEXT NOT NULL, warnings TEXT NOT NULL DEFAULT '', unsupported TEXT NOT NULL DEFAULT '');
CREATE TABLE import_source_item(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES import_run(id) ON DELETE CASCADE, source_document_id TEXT NOT NULL, source_sheet TEXT, source_row INTEGER, item_fingerprint TEXT NOT NULL, inventory_type TEXT NOT NULL, raw_fields TEXT NOT NULL DEFAULT '', mapping_decision TEXT NOT NULL DEFAULT '', UNIQUE(run_id,source_document_id));
CREATE TABLE entity_provenance(id TEXT PRIMARY KEY, source_item_id TEXT NOT NULL REFERENCES import_source_item(id) ON DELETE CASCADE, destination_type TEXT NOT NULL, destination_id TEXT NOT NULL, source_field TEXT, destination_field TEXT, mapping TEXT NOT NULL DEFAULT '');
CREATE INDEX provenance_destination ON entity_provenance(destination_type,destination_id);
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT INTO schema_migrations(version,applied_at) VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
